if(typeof NoteModel!=='undefined'&&NoteModel.extend)NoteModel.extend({dictionary:CATALOG_STUDIO.dictionary});
for(const r of CATALOG_STUDIO.items){if(byId(r.id))continue;const noteWeights=NoteModel.weights(r.notes);const vector=(r.vector&&r.vector.length===24?r.vector:NoteModel.buildVector(noteWeights)).map(x=>Math.max(0,Math.min(1,x)));PERFUMES.push({...r,vector,noteWeights,origin:'studio'});}
if(typeof INGREDIENTS!=='undefined')for(const i of CATALOG_STUDIO.ingredients){if(INGREDIENTS.some(x=>x.id===i.id))continue;let fam=0;try{const v=NoteModel.vector(i.name);let b=-1;v.forEach((x,k)=>{if(x>b){b=x;fam=k;}});}catch(e){}INGREDIENTS.push({...i,family:fam,illustrated:true});}
